function validate([n, requests]) {
  if (!Number.isInteger(n) || n < 1 || n > 20) return 'n is between 1 and 20.';
  if (!Array.isArray(requests) || requests.length < 1 || requests.length > 16) return 'requests needs 1 to 16 entries.';
  for (const pair of requests) {
    if (!Array.isArray(pair) || pair.length !== 2) return 'Each request is a pair [from, to].';
    if (pair.some(b => !Number.isInteger(b) || b < 0 || b >= n)) return 'Each building number is between 0 and n - 1.';
  }
  return null;
}

