function maximumRequests(n, requests) {
  const m = requests.length;
  let best = 0;
  for (let mask = 1; mask < 1 << m; mask++) {
    const balance = new Array(n).fill(0);
    let chosen = 0;
    for (let i = 0; i < m; i++) {
      if ((mask >> i) & 1) {
        const [from, to] = requests[i];
        balance[from]--;
        balance[to]++;
        chosen++;
      }
    }
    if (chosen > best && balance.every(net => net === 0)) {
      best = chosen;
    }
  }
  return best;
}

