function maximumRequests(n, requests) {
  // Recursive include/exclude search that undoes each choice on the way back.
  const balance = new Array(n).fill(0);
  let best = 0;
  const go = (index, taken) => {
    if (index === requests.length) {
      if (balance.every(v => v === 0)) best = Math.max(best, taken);
      return;
    }
    go(index + 1, taken);
    const [a, b] = requests[index];
    balance[a] -= 1;
    balance[b] += 1;
    go(index + 1, taken + 1);
    balance[a] += 1;
    balance[b] -= 1;
  };
  go(0, 0);
  return best;
}

