function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const large = size === 'large';
  const n = large ? (rand() < 0.5 ? int(3, 6) : int(10, 20)) : int(1, 5);
  const m = large ? 16 : int(1, 10);
  const requests = [];
  while (requests.length < m) {
    // Sometimes add a whole cycle so that large answers appear.
    if (rand() < 0.3) {
      const length = int(1, Math.min(n, 4, m - requests.length));
      const stops = Array.from({ length }, () => int(0, n - 1));
      for (let i = 0; i < length; i++) requests.push([stops[i], stops[(i + 1) % length]]);
    } else {
      requests.push([int(0, n - 1), int(0, n - 1)]);
    }
  }
  // Shuffle so cycle members are not adjacent.
  for (let i = requests.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [requests[i], requests[j]] = [requests[j], requests[i]];
  }
  return [n, requests];
}
